fn order(self: *Inventory, token: []const u8) Error!*Order {
    const n = integer(token);
    if (n < 1 or n > @as(i64, @intCast(self.orders.items.len))) return self.fail("unknown order {s}", .{token});
    return self.orders.items[@intCast(n - 1)];
